package dev.veltraph.client.chocolate;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static dev.veltraph.client.chocolate.ChocolateFactoryTest.*;
class ChocolateUpgradeRepeatTest {
    record Setup(Port port,ChocolateFactoryRuntime runtime,ChocolateUpgradeRepeat repeat){}
    static Setup ack(String budget,String reserve){var p=new Port();var rt=new ChocolateFactoryRuntime(p);assertTrue(rt.selectQueue(profile(),observation(1,1,"200","old"),List.of("employee"),n(budget),n(reserve),1000));var repeat=new ChocolateUpgradeRepeat("employee",2,2000);rt.tick(profile(),1000);p.observation=observation(2,2,"100","new");rt.tick(profile(),1500);assertEquals(ChocolateFactoryRuntime.State.ACKNOWLEDGED,rt.state());return new Setup(p,rt,repeat);}
    static ChocolateUpgradeRepeat.Result advance(Setup s,ChocolateFactoryObservation o,long time){return s.repeat().advance(s.runtime(),profile(),o,-1,time,()->true);}
    @Test void eachLevelRequiresItsActualNewQuoteAndAcknowledgment(){var s=ack("200","0");s.repeat().acknowledgedDurably(s.runtime(),1500);assertEquals(ChocolateUpgradeRepeat.Result.SELECTED,advance(s,s.port().observation,1500));assertEquals(2,s.runtime().selection().quote().level());s.runtime().tick(profile(),1500);s.port().observation=observation(3,3,"0","newer");s.runtime().tick(profile(),2000);s.repeat().acknowledgedDurably(s.runtime(),2000);assertEquals(ChocolateUpgradeRepeat.Result.STOPPED,advance(s,s.port().observation,2000));assertEquals(n("200"),s.runtime().spent());assertEquals(2,s.port().clicks);assertEquals(2,s.runtime().acknowledgedUpgrades().size());}
    @Test void waitUsesObservedWalletAndPreservesReserve(){var s=ack("250","50");s.repeat().acknowledgedDurably(s.runtime(),1500);assertEquals(ChocolateUpgradeRepeat.Result.WAITING,advance(s,s.port().observation,1600));assertEquals(1,s.port().clicks);assertEquals(ChocolateUpgradeRepeat.Result.SELECTED,advance(s,observation(3,2,"150","new"),2000));assertEquals(n("50"),s.runtime().selection().reserve());}
    @Test void cumulativeBudgetStopsEvenWithAnAffordableWallet(){var s=ack("150","0");s.repeat().acknowledgedDurably(s.runtime(),1500);assertEquals(ChocolateUpgradeRepeat.Result.STOPPED,advance(s,observation(3,2,"300","new"),2000));assertEquals(1,s.port().clicks);assertEquals(n("100"),s.runtime().spent());}
    @Test void changedPriceOrExternallyChangedTargetRequiresFreshDeliberateSelection(){for(boolean price:List.of(false,true)){var s=ack("300","0");s.repeat().acknowledgedDurably(s.runtime(),1500);var o=observation(3,price?2:3,"200",price?"changed":"newer");if(price){var q=o.quotes().get("employee");var changed=new ChocolateFactoryObservation.Quote(q.id(),q.kind(),q.slot(),q.level(),n("101"),q.fullIdentity(),q.productionDelta(),q.assumption());o=new ChocolateFactoryObservation(o.scope(),o.session(),o.menu(),o.screen(),o.revision(),o.observedMillis(),o.title(),true,true,o.rows(),o.balance(),o.production(),o.capacity(),o.prestigeProgress(),o.prestigeGoal(),Map.of("employee",changed));}assertEquals(ChocolateUpgradeRepeat.Result.STOPPED,advance(s,o,2000));assertEquals(1,s.port().clicks);}}
    @Test void incompleteNativeFrameDefersWithoutAuthorizingInput(){var s=ack("250","50");s.repeat().acknowledgedDurably(s.runtime(),1500);var o=s.port().observation;var partial=new ChocolateFactoryObservation(o.scope(),o.session(),o.menu(),o.screen(),3,1700,o.title(),false,true,o.rows(),o.balance(),o.production(),o.capacity(),o.prestigeProgress(),o.prestigeGoal(),Map.of(),Map.of(),true);assertEquals(ChocolateUpgradeRepeat.Result.WAITING,advance(s,partial,1700));assertEquals(1,s.port().clicks);}
    @Test void freshPacketsCannotExtendOriginalWaitAndClockReversalStops(){for(boolean reversed:List.of(false,true)){var s=ack("250","50");s.repeat().acknowledgedDurably(s.runtime(),1500);assertEquals(ChocolateUpgradeRepeat.Result.WAITING,advance(s,observation(3,2,"100","new"),3000));assertEquals(ChocolateUpgradeRepeat.Result.STOPPED,advance(s,observation(4,2,"100","new"),reversed?1499:3501));assertEquals(1,s.port().clicks);}}
    @Test void unknownOrCancellationCannotAdvanceAnotherRequest(){var s=ack("250","0");s.repeat().acknowledgedDurably(s.runtime(),1500);assertEquals(ChocolateUpgradeRepeat.Result.SELECTED,advance(s,s.port().observation,1500));s.runtime().tick(profile(),1500);s.runtime().cancel();assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,s.runtime().state());assertEquals(ChocolateUpgradeRepeat.Result.STOPPED,advance(s,observation(3,3,"0","newer"),2000));assertEquals(2,s.port().clicks);assertEquals(n("100"),s.runtime().spent());}
    @Test void durableAcknowledgmentIsRequiredAndCannotBeCountedTwice(){var s=ack("300","0");assertEquals(ChocolateUpgradeRepeat.Result.STOPPED,advance(s,s.port().observation,1500));s.repeat().acknowledgedDurably(s.runtime(),1500);s.repeat().acknowledgedDurably(s.runtime(),1600);assertTrue(s.repeat().diagnostics().contains("1/2"));assertEquals(ChocolateUpgradeRepeat.Result.SELECTED,advance(s,s.port().observation,1700));}
    @Test void contextCursorInventoryAndFinalAuthorityVetoNextSelection(){for(int fault=0;fault<5;fault++){boolean allow=fault!=4;var s=ack("300","0");s.repeat().acknowledgedDurably(s.runtime(),1500);var o=s.port().observation;var rows=new HashMap<>(o.rows());if(fault==2)rows.remove(10);var wrong=new ChocolateFactoryObservation(o.scope(),fault==0?new Object():o.session(),o.menu(),o.screen(),3,1700,o.title(),true,fault!=1,rows,o.balance(),o.production(),o.capacity(),o.prestigeProgress(),o.prestigeGoal(),o.quotes());assertEquals(ChocolateUpgradeRepeat.Result.STOPPED,s.repeat().advance(s.runtime(),profile(),wrong,fault==3?0:-1,1700,()->allow));assertEquals(1,s.port().clicks);}}
    @Test void selectingNextObservedQuoteRetiresPreviousDispatchClockBeforeAnyNewInput(){var s=ack("200","0");assertEquals(1000,s.runtime().requestSentAtMillis());s.repeat().acknowledgedDurably(s.runtime(),1500);assertEquals(ChocolateUpgradeRepeat.Result.SELECTED,advance(s,s.port().observation,1500));assertEquals(0,s.runtime().requestSentAtMillis());assertEquals(1,s.port().clicks);s.runtime().cancel();assertEquals(ChocolateFactoryRuntime.State.IDLE,s.runtime().state());assertEquals(0,s.runtime().requestSentAtMillis());}

}
